```cpp
#include <iostream>
using namespace std;
class MyClass {
public:
    MyClass(){
        cout << "Constructor called!" << endl;
    }
    void display(){
        cout << "Display function called!"<< endl;
    }
};
int main(){
    MyClass* obj = NULL;
    obj->display();
    return 0;
}
```

