void processData(){
    stack<int> s;
    queue<int> q;
    for (int i = 1; i <= 5; ++i){
        s.push(i);
        q.push(i);
    }
    while(!s.empty()){
        cout << "Stack pop: "<< s.top()<< endl;
        s.pop();
    }
    while(!q.empty()){
        cout << "Queue pop: "<< q.front()<< endl;
        q.pop();
    }
}
```

根据下面二叉树和给定的代码，
```cpp
#include <iostream>
using namespace std;
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL){}
};
TreeNode* search(TreeNode* root, int val) {
    cout << root->val << " ";
    if (root == NULL || root->val == val) return root;
    if (val < root->val)
        return search(root->left, val);
    else
        return search(root->right, val);
}
```
